#!/usr/bin/env node
/**
 * validate-config.mjs
 *
 * Valida dock-ds.config.json contra o JSON Schema oficial.
 * Bloqueia se:
 *   - Schema inválido (campos faltando, tipos errados)
 *   - Exception sem expiresAt + ticket
 *   - Exception com expiresAt passado (já venceu)
 *
 * Uso:
 *   node node_modules/@dock-tech/shared-copilot-front-lib/copilot-config/scripts/validate-config.mjs
 *
 * No CI:
 *   npm run validate:config
 */

import { readFileSync, existsSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const PKG_ROOT = join(__dirname, '..');
const PROJECT_ROOT = process.cwd();

const CONFIG_PATH = join(PROJECT_ROOT, 'dock-ds.config.json');
const SCHEMA_PATH = join(PKG_ROOT, 'schemas', 'dock-ds-config.schema.json');

// ── Cores no console ─────────────────────────────────────────
const R = '\x1b[31m';
const G = '\x1b[32m';
const Y = '\x1b[33m';
const C = '\x1b[36m';
const RESET = '\x1b[0m';

function fail(msg) {
  console.error(`${R}❌ ${msg}${RESET}`);
  process.exit(1);
}

function warn(msg) {
  console.warn(`${Y}⚠️  ${msg}${RESET}`);
}

function ok(msg) {
  console.log(`${G}✅ ${msg}${RESET}`);
}

// ── Pre-checks ─────────────────────────────────────────────
if (!existsSync(CONFIG_PATH)) {
  warn('dock-ds.config.json não encontrado. Pulando validação.');
  process.exit(0);
}

if (!existsSync(SCHEMA_PATH)) {
  fail(`Schema não encontrado em ${SCHEMA_PATH}. Reinstale @dock-tech/shared-copilot-front-lib.`);
}

// ── Load ───────────────────────────────────────────────────
let config, schema;
try {
  config = JSON.parse(readFileSync(CONFIG_PATH, 'utf-8'));
} catch (e) {
  fail(`dock-ds.config.json inválido (JSON malformado): ${e.message}`);
}

try {
  schema = JSON.parse(readFileSync(SCHEMA_PATH, 'utf-8'));
} catch (e) {
  fail(`Schema inválido: ${e.message}`);
}

// ── Schema validation (Ajv opcional, fallback manual) ──────
// Para evitar dep pesada, faço validação focal das regras críticas
console.log(`${C}🔍 Validando dock-ds.config.json...${RESET}\n`);

const errors = [];

// 1. Campos obrigatórios no root
if (!config.name || typeof config.name !== 'string') {
  errors.push('Campo "name" obrigatório (string).');
}

// 2. Components.preferImport: cada item deve seguir Ds*
if (config.components?.preferImport) {
  if (!Array.isArray(config.components.preferImport)) {
    errors.push('components.preferImport deve ser array.');
  } else {
    for (const c of config.components.preferImport) {
      if (!/^Ds[A-Z][a-zA-Z]+$/.test(c)) {
        errors.push(`components.preferImport["${c}"] não segue padrão DsXxx.`);
      }
    }
  }
}

// 3. Tokens.colors: hex sem #
if (config.tokens?.colors) {
  if (!Array.isArray(config.tokens.colors)) {
    errors.push('tokens.colors deve ser array.');
  } else {
    for (const c of config.tokens.colors) {
      if (!/^[0-9a-fA-F]{6}([0-9a-fA-F]{2})?$/.test(c)) {
        errors.push(`tokens.colors["${c}"] deve ser hex sem # (6 ou 8 chars).`);
      }
    }
  }
}

// 4. Exceptions — CRÍTICO: precisam expirar
if (config.exceptions) {
  if (!Array.isArray(config.exceptions)) {
    errors.push('exceptions deve ser array.');
  } else {
    const today = new Date().toISOString().slice(0, 10);
    for (const [i, ex] of config.exceptions.entries()) {
      const prefix = `exceptions[${i}]`;

      if (!ex.rule) errors.push(`${prefix}.rule obrigatório.`);
      if (!ex.reason || ex.reason.length < 20) {
        errors.push(`${prefix}.reason precisa ter pelo menos 20 chars (justificativa real).`);
      }
      if (!ex.expiresAt) {
        errors.push(`${prefix}.expiresAt obrigatório. Toda exceção tem prazo de validade.`);
      } else {
        if (!/^\d{4}-\d{2}-\d{2}$/.test(ex.expiresAt)) {
          errors.push(`${prefix}.expiresAt deve ser data ISO (YYYY-MM-DD), recebido "${ex.expiresAt}".`);
        } else if (ex.expiresAt < today) {
          errors.push(
            `${prefix} EXPIROU em ${ex.expiresAt} (hoje: ${today}). ` +
            `Resolva o ticket ${ex.ticket || 'N/A'} ou renove a exceção.`
          );
        }
      }
      if (!ex.ticket) {
        errors.push(`${prefix}.ticket obrigatório (Jira/Linear/GitHub Issue).`);
      } else if (!/^(JIRA-\d+|LINEAR-\w+|#\d+|GH-\d+)$/.test(ex.ticket)) {
        errors.push(`${prefix}.ticket "${ex.ticket}" formato inválido. Use JIRA-123, LINEAR-abc, #42 ou GH-42.`);
      }
    }
  }
}

// ── Output ─────────────────────────────────────────────────
if (errors.length === 0) {
  ok(`dock-ds.config.json válido (${config.exceptions?.length || 0} exceções ativas)`);
  if (config.exceptions?.length > 0) {
    console.log(`${C}\nExceções ativas:${RESET}`);
    for (const ex of config.exceptions) {
      console.log(`  • ${ex.rule} → expira em ${ex.expiresAt} (ticket: ${ex.ticket})`);
    }
  }
  process.exit(0);
}

console.error(`${R}\n${errors.length} erro(s) de validação:${RESET}\n`);
for (const err of errors) {
  console.error(`  • ${err}`);
}
console.error(`\n${R}❌ Build bloqueado. Corrija o dock-ds.config.json.${RESET}\n`);
process.exit(1);
